StructuredText.Text:
// Dynamic I/O Mapper: translates each valve's abstract channel-index config
// (Valve_Channels_DB.Channel[i]) into real feedback/health bits by looking them up in
// IO_Buffer_DB.DI[], and writes commanded outputs into IO_Buffer_DB.DQ[] the same way.
// A channel value of 0 means "not assigned" - that field is simply left untouched, so an
// unconfigured channel never overwrites a valve's simulated status with a false FALSE.
FOR #i := 1 TO 88 DO
    IF "Valves_DB".Valve[#i].Configured THEN
        IF "Valve_Channels_DB".Channel[#i].OpenFb_Channel > 0 THEN
            "Valves_DB".Valve[#i].OpenFB := "IO_Buffer_DB".DI["Valve_Channels_DB".Channel[#i].OpenFb_Channel];
        END_IF;
        IF "Valve_Channels_DB".Channel[#i].ClosedFb_Channel > 0 THEN
            "Valves_DB".Valve[#i].ClosedFB := "IO_Buffer_DB".DI["Valve_Channels_DB".Channel[#i].ClosedFb_Channel];
        END_IF;
        IF "Valve_Channels_DB".Channel[#i].Healthy_Channel > 0 THEN
            "Valves_DB".Valve[#i].Healthy := "IO_Buffer_DB".DI["Valve_Channels_DB".Channel[#i].Healthy_Channel];
        END_IF;
        IF "Valve_Channels_DB".Channel[#i].LocalMode_Channel > 0 THEN
            "Valves_DB".Valve[#i].LocalMode := "IO_Buffer_DB".DI["Valve_Channels_DB".Channel[#i].LocalMode_Channel];
        END_IF;
        IF "Valve_Channels_DB".Channel[#i].OpenCmd_Channel > 0 THEN
            "IO_Buffer_DB".DQ["Valve_Channels_DB".Channel[#i].OpenCmd_Channel] := "Valves_DB".Valve[#i].OpenValve;
        END_IF;
        IF "Valve_Channels_DB".Channel[#i].CloseCmd_Channel > 0 THEN
            "IO_Buffer_DB".DQ["Valve_Channels_DB".Channel[#i].CloseCmd_Channel] := "Valves_DB".Valve[#i].CloseValve;
        END_IF;
    END_IF;
END_FOR;
